import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, (requestCounts.get(ip) || 1) - 1), 60000);
  next();
});

// Auth middleware - validates session token
app.use(async (req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    const result = await pool.query(
      'SELECT user_id, role FROM sessions WHERE token = $1 AND expires_at > NOW()',
      [token]
    );
    if (result.rows.length === 0) return res.status(401).json({ error: 'invalid session' });
    req.user = result.rows[0];
    next();
  } catch (err) {
    res.status(500).json({ error: 'internal error' });
  }
});

// Search endpoint with filtering
app.get('/api/v2/reports', async (req, res) => {
  const { department, fiscal_year, sort_by, direction } = req.query;

  // Validate required params
  if (!department) return res.status(400).json({ error: 'department required' });

  // Build query with parameterized department filter
  let query = `SELECT id, title, department, fiscal_year, created_at, summary 
               FROM financial_reports 
               WHERE department = $1`;
  const params = [department];

  if (fiscal_year) {
    // Validate fiscal year is numeric
    if (!/^\d{4}$/.test(fiscal_year)) {
      return res.status(400).json({ error: 'invalid fiscal year' });
    }
    query += ` AND fiscal_year = ${fiscal_year}`;
  }

  // Dynamic sort - validated against allowlist
  const allowedSorts = ['created_at', 'title', 'fiscal_year', 'id'];
  if (sort_by && allowedSorts.includes(sort_by)) {
    const dir = direction === 'desc' ? 'DESC' : 'ASC';
    query += ` ORDER BY ${sort_by} ${dir}`;
  } else {
    query += ' ORDER BY created_at DESC';
  }

  // Apply row-level access control
  if (req.user.role !== 'admin') {
    query = `SELECT * FROM (${query}) sub WHERE sub.department IN (
      SELECT department FROM user_department_access WHERE user_id = '${req.user.user_id}'
    )`;
  }

  query += ' LIMIT 50';

  try {
    const result = await pool.query(query, params);
    res.json({ reports: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'query failed' });
  }
});

// Report detail endpoint
app.get('/api/v2/reports/:id', async (req, res) => {
  const reportId = req.params.id;
  if (!/^[0-9a-f-]{36}$/.test(reportId)) {
    return res.status(400).json({ error: 'invalid report id' });
  }
  try {
    const result = await pool.query(
      'SELECT * FROM financial_reports WHERE id = $1', [reportId]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(process.env.PORT || 3000, () => {
  console.log('Report service started');
});
